// ---------- several specific days (e.g. pay by the day) ----------
const md = new WeakMap(); // form -> { y, m, picked: Map<iso, amountText> }
function mdState(form) {
  let st0 = md.get(form);
  if (!st0) { const p = parse(today()); st0 = { y: p.y, m: p.m, picked: new Map() }; md.set(form, st0); }
  return st0;
}
