  for (let d = 1; d <= daysInMonth(s0.y, s0.m); d++) { const iso = toIso(s0.y, s0.m, d), w = dow(iso); if (iso >= today() && w >= 1 && w <= 5 && !s0.picked.has(iso)) s0.picked.set(iso, f.elements.amount?.value || ''); }
