// distinct, calm colours that stay readable on both light and dark cards
const SLICE_COLORS = ['#8A7090', '#A4AF69', '#C98B5E', '#5F8FB8', '#C77D96', '#4F8A6A', '#D1A24A', '#7C79C2'];
