    if (/,\d{1,2}\s*[A-Za-z€$£]*\)?$/.test(t) && !/\.\d{1,2}$/.test(t)) comma++;
    if (/\.\d{1,2}\s*[A-Za-z€$£]*\)?$/.test(t) && !/,\d{1,2}$/.test(t)) dot++;
